def test_property_one_in_corner():
    # 1 in corner has only 2 neighbors; bounce must still hold
    grid = [[1, 5, 6], [7, 8, 9], [4, 3, 2]]
    mn = min_neighbor_of_one(grid)
    for k in [2, 3, 4, 5]:
        out = minPath(grid, k)
        assert out == [1 if i % 2 == 0 else mn for i in range(k)]
        assert out == brute_min_path(grid, k)


def test_property_one_in_center():
    grid = [[5, 9, 3], [4, 1, 6], [7, 8, 2]]
    # neighbors of 1: 9,4,6,8 -> min 4
    assert min_neighbor_of_one(grid) == 4
    assert minPath(grid, 2) == [1, 4]
    assert minPath(grid, 3) == [1, 4, 1]
    assert minPath(grid, 4) == [1, 4, 1, 4]


def test_property_one_on_edge():
    grid = [[2, 1, 3], [4, 5, 6], [7, 8, 9]]
    # neighbors: 2,3,5 -> min 2
    assert min_neighbor_of_one(grid) == 2
    assert minPath(grid, 3) == [1, 2, 1]
    assert minPath(grid, 4) == [1, 2, 1, 2]


def test_property_lexicographically_minimal_explicit():
    # hand-crafted case where greedy-by-value could be tempted to leave 1's region
    grid = [[2, 3, 4], [5, 1, 6], [7, 8, 9]]
    # neighbors of 1: 3,5,6,8 -> min 3
    for k in [1, 2, 3, 4, 5]:
        out = minPath(grid, k)
        for w in all_walks(grid, k):
            assert out <= w
        assert out == brute_min_path(grid, k)


@given(grid2_strategy, st.integers(1, 6))
def test_property_lexicographically_minimal_2x2(grid, k):
    out = minPath(grid, k)
    # check minimality against brute force enumeration directly
    best = brute_min_path(grid, k)
    assert out == best
    for w in all_walks(grid, k):
        assert out <= w


def test_property_k_large_bounce():
    # long k must keep bouncing between 1 and its best neighbor
    grid = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    mn = min_neighbor_of_one(grid)
    assert mn == 2
    out = minPath(grid, 8)
    assert out == [1, 2, 1, 2, 1, 2, 1, 2]


def test_property_odd_positions_are_one():
    # any odd index (0-based even) must be 1 since 1 is global min and bounce is feasible
    grid = [[5, 9, 3], [4, 1, 6], [7, 8, 2]]
    out = minPath(grid, 6)
    for i in range(0, 6, 2):
        assert out[i] == 1
